list_blogs.code:
var response = await client.Blogs.ListBlogsAsync(
    new Dictionary<string, object?> { ["visibility"] = "open", ["limit"] = 20 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var blog in ((IReadOnlyList<object?>)body["blogs"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{blog["id"]} {blog["title"]} {blog["date"]} {blog["is_published"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");

