var response = await client.Blogs.UpdateBlogAsync(1201, new Dictionary<string, object?>
{
    ["blog"] = new Dictionary<string, object?>
    {
        ["title"] = "Spring Sale Extended", ["content"] = "<p>The spring sale now runs one more week.</p>",
        ["date"] = "2026-09-28", ["is_published"] = true, ["visibility"] = "restricted", ["visible_to"] = "selected",
        ["categories"] = new List<object?> { new Dictionary<string, object?> { ["id"] = 31 } },
        ["seo_configs"] = new Dictionary<string, object?> { ["meta_tag"] = new List<object?>
            { new Dictionary<string, object?> { ["name"] = "description", ["value"] = "Spring sale: up to 40% off" } } },
        ["selected_customers"] = new Dictionary<string, object?>
            { ["customers"] = new List<object?> { 5501 }, ["groups"] = new List<object?>() },
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var blog = (IReadOnlyDictionary<string, object?>)body["blog"]!;
Console.WriteLine($"{blog["title"]} {blog["visibility"]} {blog["visible_to"]}");
var audience = (IReadOnlyDictionary<string, object?>)blog["selected_customers"]!;
foreach (var customer in ((IReadOnlyList<object?>)audience["customers"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{customer["id"]} {customer["name"]}");

